fn rsplit(a: Vec<String>, sep: String, maxsplit: u8) -> Vec<Vec<String>> {
    let mut result = Vec::with_capacity(a.len());
    let maxsplit = maxsplit as usize; // Convert to usize for easier indexing

    for s in a {
        if maxsplit == 0 {
            // If maxsplit is 0, return the original string as a single element list
            result.push(vec![s]);
            continue;
        }

        // Split the string using the specified separator
        let mut parts: Vec<String> = s.split(&sep).map(String::from).collect();

        // If the number of splits exceeds maxsplit, we need to merge the last parts
        if parts.len() > maxsplit + 1 {
            let excess_parts = parts.split_off(parts.len() - maxsplit - 1);
            // Join the excess parts back together with the separator
            let last_part = excess_parts.join(&sep);
            parts.push(last_part);
        }

        result.push(parts);
    }

    result
}